-- #77 시장 제안 (ADR-0069 decision 4 #77, ADR-0089). Generated by `drizzle-kit generate`, then
-- hand-edited where marked: the tail. The snapshot is as generated.
--
-- - market_proposals: one row per proposal — the form as submitted (never edited), the keyed hash
--   of the proposer's verified number (the limits count by it, ADR-0069 decision 7), the status
--   (market_proposal_status) and the review: who started it and when, who decided it and when, the
--   반려's reason (market_proposal_rejection_reason) and explanation, the 채택's memo and market,
--   who linked a market later and when (a 채택 that had none, once — owner decision 2026-10-19),
--   the 철회's time, and the operators' internal memo. The CHECKs tie each status to its columns.
-- - A trigger keeps the submitted form as it was and moves the status only along the owner's
--   steps (접수 → 검토 → 채택·반려, 접수 → 반려, 접수 → 철회; 채택, 반려 and 철회 final), with the one
--   later change of a 채택: a market linked to one that has none, and the one change of the
--   number's hash: the operator's number change's (owner decision 2026-10-25, ADR-0089).
-- - buddha_app keeps every privilege of the defaults: the row moves (UPDATE), and #184's worker
--   deletes a withdrawn account's proposals once their processing has ended and their retention
--   period — '시장 제안 기록 보존기간', `retention.market_proposals` — has passed (DELETE).
-- - retention_purges_kind_check: the purge records take the new kind `market_proposals` (#184's
--   RETENTION_PURGE_KINDS, ADR-0087 결과 5; owner decision 2026-10-24 13) — the generated drop and
--   add of the CHECK, the list as before (0044's, with #187's `link_flags`) with the kind at its
--   end.
CREATE TYPE "public"."market_proposal_rejection_reason" AS ENUM('duplicate', 'ambiguous_criteria', 'prohibited_topic', 'other');--> statement-breakpoint
CREATE TYPE "public"."market_proposal_status" AS ENUM('submitted', 'reviewing', 'adopted', 'rejected', 'retracted');--> statement-breakpoint
CREATE TABLE "market_proposals" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" text NOT NULL,
	"phone_hash" varchar(64) NOT NULL,
	"question" varchar(100) NOT NULL,
	"deadline" date NOT NULL,
	"yes_condition" varchar(1000) NOT NULL,
	"expected_sources" varchar(500) NOT NULL,
	"background" varchar(5000),
	"category_id" integer,
	"status" "market_proposal_status" DEFAULT 'submitted' NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	"review_started_at" timestamp (3) with time zone,
	"review_started_by" text,
	"decided_at" timestamp (3) with time zone,
	"decided_by" text,
	"retracted_at" timestamp (3) with time zone,
	"rejection_reason" "market_proposal_rejection_reason",
	"rejection_explanation" varchar(1000),
	"duplicate_market_id" uuid,
	"adoption_memo" varchar(1000),
	"market_id" uuid,
	"market_linked_at" timestamp (3) with time zone,
	"market_linked_by" text,
	"internal_memo" varchar(1000),
	CONSTRAINT "market_proposals_phone_hash_check" CHECK ("market_proposals"."phone_hash" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "market_proposals_text_check" CHECK (btrim("market_proposals"."question") <> '' AND btrim("market_proposals"."yes_condition") <> '' AND btrim("market_proposals"."expected_sources") <> '' AND btrim("market_proposals"."background") IS DISTINCT FROM ''),
	CONSTRAINT "market_proposals_moves_check" CHECK (("market_proposals"."review_started_at" IS NULL) = ("market_proposals"."review_started_by" IS NULL) AND ("market_proposals"."decided_at" IS NULL) = ("market_proposals"."decided_by" IS NULL) AND ("market_proposals"."market_linked_at" IS NULL) = ("market_proposals"."market_linked_by" IS NULL) AND ("market_proposals"."review_started_at" IS NOT NULL OR "market_proposals"."status" NOT IN ('reviewing', 'adopted')) AND ("market_proposals"."review_started_at" IS NULL OR "market_proposals"."status" NOT IN ('submitted', 'retracted')) AND ("market_proposals"."decided_at" IS NOT NULL) = ("market_proposals"."status" IN ('adopted', 'rejected')) AND ("market_proposals"."retracted_at" IS NOT NULL) = ("market_proposals"."status" = 'retracted')),
	CONSTRAINT "market_proposals_rejection_check" CHECK (("market_proposals"."rejection_reason" IS NOT NULL) = ("market_proposals"."status" = 'rejected') AND ("market_proposals"."rejection_reason" IS NULL) = ("market_proposals"."rejection_explanation" IS NULL) AND btrim("market_proposals"."rejection_explanation") IS DISTINCT FROM '' AND coalesce("market_proposals"."rejection_reason" = 'duplicate', false) = ("market_proposals"."duplicate_market_id" IS NOT NULL)),
	CONSTRAINT "market_proposals_adoption_check" CHECK (("market_proposals"."status" = 'adopted' OR ("market_proposals"."adoption_memo" IS NULL AND "market_proposals"."market_id" IS NULL AND "market_proposals"."market_linked_at" IS NULL)) AND ("market_proposals"."market_linked_at" IS NULL OR "market_proposals"."market_id" IS NOT NULL)),
	CONSTRAINT "market_proposals_memo_check" CHECK (btrim("market_proposals"."adoption_memo") IS DISTINCT FROM '' AND btrim("market_proposals"."internal_memo") IS DISTINCT FROM '')
);
--> statement-breakpoint
ALTER TABLE "retention_purges" DROP CONSTRAINT "retention_purges_kind_check";--> statement-breakpoint
ALTER TABLE "market_proposals" ADD CONSTRAINT "market_proposals_user_id_user_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."user"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "market_proposals" ADD CONSTRAINT "market_proposals_category_id_categories_id_fk" FOREIGN KEY ("category_id") REFERENCES "public"."categories"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "market_proposals" ADD CONSTRAINT "market_proposals_review_started_by_user_id_fk" FOREIGN KEY ("review_started_by") REFERENCES "public"."user"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "market_proposals" ADD CONSTRAINT "market_proposals_decided_by_user_id_fk" FOREIGN KEY ("decided_by") REFERENCES "public"."user"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "market_proposals" ADD CONSTRAINT "market_proposals_duplicate_market_id_markets_id_fk" FOREIGN KEY ("duplicate_market_id") REFERENCES "public"."markets"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "market_proposals" ADD CONSTRAINT "market_proposals_market_id_markets_id_fk" FOREIGN KEY ("market_id") REFERENCES "public"."markets"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "market_proposals" ADD CONSTRAINT "market_proposals_market_linked_by_user_id_fk" FOREIGN KEY ("market_linked_by") REFERENCES "public"."user"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "market_proposals_user_id_created_at_id_idx" ON "market_proposals" USING btree ("user_id","created_at" desc,"id" desc);--> statement-breakpoint
CREATE INDEX "market_proposals_phone_hash_created_at_idx" ON "market_proposals" USING btree ("phone_hash","created_at");--> statement-breakpoint
CREATE INDEX "market_proposals_phone_hash_pending_idx" ON "market_proposals" USING btree ("phone_hash") WHERE "market_proposals"."status" IN ('submitted', 'reviewing');--> statement-breakpoint
CREATE INDEX "market_proposals_created_at_id_idx" ON "market_proposals" USING btree ("created_at" desc,"id" desc);--> statement-breakpoint
CREATE INDEX "market_proposals_status_created_at_id_idx" ON "market_proposals" USING btree ("status","created_at" desc,"id" desc);--> statement-breakpoint
ALTER TABLE "retention_purges" ADD CONSTRAINT "retention_purges_kind_check" CHECK ("retention_purges"."kind" IN ('nickname_holds', 'post_revisions', 'comment_revisions', 'deleted_posts', 'deleted_comments', 'reports', 'hidden_posts', 'hidden_comments', 'removed_profile_items', 'moderation_actions', 'approval_requests', 'link_flags', 'consent_records', 'phone_verification_records', 'market_proposals'));--> statement-breakpoint
-- Hand-edited: what was submitted never changes, and the status moves only along the owner's steps
-- (ADR-0069 decision 4 #77; PROPOSAL_TRANSITIONS in @buddha/shared), whoever writes — the API checks
-- the same under the row lock and never asks for anything else. A proposal is inserted 접수
-- (`submitted`); a row keeps its status unless it moves, and then its earlier moves stay as they
-- were (a 검토's start through the decision after it); a 반려 straight from 접수 records no review
-- start; 채택, 반려 and 철회 move nowhere. Without a move, the operators' internal memo changes, and
-- one thing more (owner decision 2026-10-19, `canLinkProposalMarket` in @buddha/shared): a 채택
-- with no market takes one, with who and when (`market_linked_*`) — once, since it then has a
-- market. A market that came with the 채택 is never replaced, and a move never records a link. The
-- CHECKs of the table say which columns each status fills.
-- The number's hash, which the limits count by (ADR-0069 decision 7), changes in one transaction
-- only: the operator's change of the proposer's number (docs/OPERATIONS.md step 5,
-- OPERATOR_PHONE_CHANGE_SQL — owner decision 2026-10-25 «신고처럼 옮김», ADR-0089), which moves
-- the person's waiting and recent proposals to the new number's hash, as #50's reports_keep_record
-- (migration 0039) takes it for the reports. Its SET LOCAL lines name the account and the two
-- hashes; the trigger takes the change to the new hash they name, of a proposal of the account
-- they name or of one under the old hash they name whose proposer has no 본인확인 record left (it
-- withdrew: the account inherited it on that number), and nothing else of the row with it. The app
-- names none of them, so none of its writes changes a hash. Which proposals move is the
-- procedure's: the trigger allows, it does not choose.
CREATE FUNCTION market_proposals_keep_record() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'submitted' THEN
      RAISE EXCEPTION 'a market proposal starts submitted, not %', NEW.status
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.phone_hash IS DISTINCT FROM OLD.phone_hash THEN
    IF (NEW.phone_hash = current_setting('phone_change.new_hash', true)
        AND (OLD.user_id = current_setting('phone_change.user_id', true)
          OR (OLD.phone_hash = current_setting('phone_change.old_hash', true)
            AND NOT EXISTS (SELECT 1 FROM phone_verifications pv
              WHERE pv.user_id = OLD.user_id)))) IS NOT TRUE THEN
      RAISE EXCEPTION 'market proposal % keeps the number it was submitted with, but for the operator''s number change', OLD.id
        USING ERRCODE = 'check_violation';
    END IF;
    IF (to_jsonb(NEW) - 'phone_hash') IS DISTINCT FROM (to_jsonb(OLD) - 'phone_hash') THEN
      RAISE EXCEPTION 'market proposal % changes its number''s hash alone', OLD.id
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF (NEW.id, NEW.user_id, NEW.question, NEW.deadline, NEW.yes_condition, NEW.expected_sources,
      NEW.background, NEW.category_id, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.user_id, OLD.question, OLD.deadline, OLD.yes_condition, OLD.expected_sources,
      OLD.background, OLD.category_id, OLD.created_at) THEN
    RAISE EXCEPTION 'market proposal %: what was submitted never changes', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status = OLD.status THEN
    IF (NEW.review_started_at, NEW.review_started_by, NEW.decided_at, NEW.decided_by,
        NEW.retracted_at, NEW.rejection_reason, NEW.rejection_explanation,
        NEW.duplicate_market_id, NEW.adoption_memo)
       IS DISTINCT FROM
       (OLD.review_started_at, OLD.review_started_by, OLD.decided_at, OLD.decided_by,
        OLD.retracted_at, OLD.rejection_reason, OLD.rejection_explanation,
        OLD.duplicate_market_id, OLD.adoption_memo) THEN
      RAISE EXCEPTION 'market proposal %: a review or a decision is written only by its move', OLD.id
        USING ERRCODE = 'check_violation';
    END IF;
    IF (NEW.market_id, NEW.market_linked_at, NEW.market_linked_by)
       IS DISTINCT FROM (OLD.market_id, OLD.market_linked_at, OLD.market_linked_by)
       AND NOT (OLD.status = 'adopted' AND OLD.market_id IS NULL
                AND NEW.market_id IS NOT NULL AND NEW.market_linked_at IS NOT NULL) THEN
      RAISE EXCEPTION 'market proposal %: a market is linked later only to an adoption with none, once', OLD.id
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NOT ((OLD.status = 'submitted' AND NEW.status IN ('reviewing', 'rejected', 'retracted'))
       OR (OLD.status = 'reviewing' AND NEW.status IN ('adopted', 'rejected'))) THEN
    RAISE EXCEPTION 'market proposal %: no move from % to %', OLD.id, OLD.status, NEW.status
      USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW.review_started_at, NEW.review_started_by)
     IS DISTINCT FROM (OLD.review_started_at, OLD.review_started_by)
     AND NEW.status <> 'reviewing' THEN
    RAISE EXCEPTION 'market proposal %: only the move to reviewing records a review start', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.market_linked_at IS NOT NULL OR NEW.market_linked_by IS NOT NULL THEN
    RAISE EXCEPTION 'market proposal %: only a later link of an adoption records a link', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER market_proposals_keep_record
  BEFORE INSERT OR UPDATE ON "market_proposals"
  FOR EACH ROW EXECUTE FUNCTION market_proposals_keep_record();
